-- 10306214 | ما الفرق بين الاجتهاد والتقليد؟
UPDATE qa_questions SET
  answer = 'الاجتهادُ عند الشاطبي في الموافقات لا يحصل إلا لمن اتَّصف بوصفين: «فهمُ مقاصد الشريعة على كمالها»، و«الممكن من الاستنباط بناءً على فهمه فيها»؛ والتقليدُ أخذُ غيرِ المؤهَّل بقول المجتهد دون معرفة دليله، وهو جائز لمن ليس أهلاً للاجتهاد. لكنّ الموافقات تُقيِّد ذلك بقيدٍ مهمّ: ثمَّ ضربٌ من الاجتهاد — وهو تحقيقُ المناط، أي النظرُ في انطباق الحكم على النازلة المعيَّنة — «لا يمكن أن يُستغنى ههنا بالتقليد؛ لأن التقليد إنما يُتصوَّر بعد تحقيق مناط الحكم المقلَّد فيه»، إذ «الشريعة لم تنصّ على حكم كل جزئية على حدتها، وإنما أتت بأمور كلية وعبارات مطلقة تتناول أعدادًا لا تنحصر»، فلكلّ نازلةٍ خصوصيةٌ تحتاج نظرًا. وفي المقابل لا يلزم المجتهدَ أن يكون مجتهدًا في كل علم، «فإذًا لا ضرر على الاجتهاد مع التقليد في بعض القواعد المتعلقة بالمسألة المجتهد فيها».',
  reference = 'الموافقات للشاطبي، ت مشهور بن حسن آل سلمان (٧ أجزاء): ج٥/ص٤١–٤٢ (الطرف الأول في الاجتهاد، المسألة الثانية) وج٥/ص١٤ و٥٢ | الكلمات المفتاحية: الاجتهاد، التقليد',
  evidence = 'الموافقات ج٥/ص٤١: «الْمَسْأَلَةُ الثَّانِيَةُ: إِنَّمَا تَحْصُلُ دَرَجَةُ الِاجْتِهَادِ لِمَنِ اتَّصَفَ بِوَصْفَيْنِ: أَحَدُهُمَا: فَهْمُ مَقَاصِدِ الشَّرِيعَةِ عَلَى كمالها»، وتمامُه ج٥/ص٤٢: «والثاني: الممكن مِنَ الِاسْتِنْبَاطِ بِنَاءً عَلَى فَهْمِهِ فِيهَا». وفي تحقيق المناط ج٥/ص١٤: «فَلَا يُمْكِنُ أَنْ يُسْتَغْنَى ههنا بِالتَّقْلِيدِ؛ لِأَنَّ التَّقْلِيدَ إِنَّمَا يُتَصَوَّرُ بَعْدَ تَحْقِيقِ مَنَاطِ الْحُكْمِ الْمُقَلَّدِ فِيهِ، وَالْمَنَاطُ هُنَا لَمْ يَتَحَقَّقْ بَعْدُ؛ لِأَنَّ كُلَّ صُورَةٍ مِنْ صُوَرِهِ النَّازِلَةِ نَازِلَةٌ مُسْتَأْنَفَةٌ فِي نَفْسِهَا لَمْ يَتَقَدَّمْ لَهَا نَظِيرٌ… فَلَا بُدَّ مِنَ النَّظَرِ فِيهَا بِالِاجْتِهَادِ»، وعلّتُه: «أَنَّ الشَّرِيعَةَ لَمْ تَنُصَّ عَلَى حُكْمِ كُلِّ جُزْئِيَّةٍ عَلَى حِدَتِهَا، وَإِنَّمَا أَتَتْ بِأُمُورٍ كُلِّيَّةٍ وَعِبَارَاتٍ مُطْلَقَةٍ تَتَنَاوَلُ أَعْدَادًا لَا تَنْحَصِرُ». وفي أن التقليد لا يُبطل الاجتهاد مطلقًا ج٥/ص٥٢: «فَإِذًا لَا ضَرَرَ عَلَى الِاجْتِهَادِ مَعَ التَّقْلِيدِ فِي بَعْضِ الْقَوَاعِدِ الْمُتَعَلِّقَةِ بِالْمَسْأَلَةِ الْمُجْتَهَدِ فِيهَا».',
  verification_status = 'verified'
WHERE id = '10306214-d281-41d4-9be3-6a676241825f'
  AND reference = 'كتب أصول الفقه | الكلمات المفتاحية: الاجتهاد، التقليد'
  AND evidence = 'مبحث أصولي مبسوط في كتب أصول الفقه.'
  AND answer = 'الاجتهاد بذل الفقيه المؤهَّل جهده لاستنباط الحكم الشرعي من أدلته التفصيلية، والتقليد أخذ العامي أو غير المؤهَّل بقول مجتهد دون معرفة دليله، وهو جائز لمن ليس أهلاً للاجتهاد.';

-- 230b8ae7 | ما حكم الدعوة إلى الله عبر وسائل التواصل الحديثة؟
UPDATE qa_questions SET
  answer = 'مشروعةٌ بل مطلوبة، تخريجًا على قاعدة الوسائل — ولفظُها في الموافقات: «الوسائل من حيث هي وسائل غير مقصودة لأنفسها، وإنما هي تبعٌ للمقاصد»؛ فما كان وسيلةً إلى مقصودٍ مشروعٍ كتبليغ الدين أخذ حكمَ مقصوده ما دام مباحًا في ذاته. ويقيِّدها ضابطُ سدّ الذرائع، وهو عند الشاطبي «أصلٌ متفق عليه في الجملة، وإن اختلف العلماء في تفاصيله»: فالوسيلة المباحة في أصلها قد يُمنع منها إذا أفضت إلى مفسدة. وهذا تخريجٌ على القاعدة، لا نصٌّ في المسألة المعاصرة بعينها.',
  reference = 'الموافقات للشاطبي، ت مشهور بن حسن آل سلمان (٧ أجزاء): ج٢/ص٣٥٣ (النوع الرابع في بيان قصد الشارع في دخول المكلف تحت أحكام الشريعة) وج٣/ص٥٠٩ | الكلمات المفتاحية: الدعوة عبر الإنترنت',
  evidence = 'القاعدةُ التي يُبنى عليها الجواب بلفظها في الموافقات ج٢/ص٣٥٣: «وَقَدْ تَقَرَّرَ أَنَّ الْوَسَائِلَ مِنْ حَيْثُ هِيَ وَسَائِلُ غَيْرُ مَقْصُودَةٍ لِأَنْفُسِهَا، وَإِنَّمَا هِيَ تَبَعٌ لِلْمَقَاصِدِ بِحَيْثُ لَوْ سَقَطَتِ الْمَقَاصِدُ سَقَطَتِ الْوَسَائِلُ، وَبِحَيْثُ لَوْ تُوُصِّلَ إِلَى الْمَقَاصِدِ دُونَهَا لَمْ يُتَوَسَّلْ بِهَا، وَبِحَيْثُ لَوْ فَرَضْنَا عَدَمَ الْمَقَاصِدِ جُمْلَةً لَمْ يَكُنْ لِلْوَسَائِلِ اعْتِبَارٌ، بَلْ كَانَتْ تَكُونُ كَالْعَبَثِ». وضابطُها المُقيِّد ج٣/ص٥٠٩: «فباب سد الذرائع… رَاجِعٌ إِلَى طَلَبِ تَرْكِ مَا ثَبَتَ طَلَبُ فِعْلِهِ لِعَارِضٍ يَعْرِضُ، وَهُوَ أَصْلٌ مُتَّفَقٌ عَلَيْهِ فِي الْجُمْلَةِ، وَإِنِ اخْتَلَفَ الْعُلَمَاءُ فِي تَفَاصِيلِهِ». ⚠️ والتطبيقُ على الوسائل الحديثة مسألةٌ معاصرة لا نصَّ فيها في الموافقات، وإنما تخريجٌ على هذه القاعدة.',
  verification_status = 'verified'
WHERE id = '230b8ae7-33f8-45bc-a1af-94f7ded9e881'
  AND reference = 'كتب أصول الفقه | الكلمات المفتاحية: الدعوة عبر الإنترنت'
  AND evidence = 'قاعدة فقهية عامة: للوسائل حكم المقاصد.'
  AND answer = 'مشروعة بل مطلوبة، فالوسيلة تتبع حكم الغاية ما دامت مباحة في ذاتها، وقد استخدم الدعاة المعاصرون هذه الوسائل لنشر الخير على نطاق واسع لم يكن ممكنًا سابقًا.';

-- 33ea59a5 | ما معنى القياس في أصول الفقه؟
UPDATE qa_questions SET
  answer = 'إلحاقُ واقعةٍ لا نصّ فيها بواقعةٍ منصوصٍ على حكمها لاشتراكهما في علة الحكم — ولفظُ الشاطبي في الموافقات: «إلحاق المسكوت عنه بالمنصوص عليه»؛ وهو رابعُ الأدلة الشرعية عنده بعد الكتاب والسنة والإجماع. ويُقيِّده الشاطبي بقيدٍ مهمّ: «ليس القياس من تصرفات العقول محضًا، وإنما تصرَّفتْ فيه من تحت نظر الأدلة، وعلى حسب ما أعطته من إطلاق أو تقييد»، وحكمُ العقل فيه تابعٌ: «بل هو مهتدٍ فيه بالأدلة الشرعية، يجري بمقدار ما أجرته، ويقف حيث وقفته» — فليس اعتبارُه استقلالًا للعقل بالتشريع، بل هو أمرٌ دلّ الشرع نفسُه على اعتباره.',
  reference = 'الموافقات للشاطبي، ت مشهور بن حسن آل سلمان (٧ أجزاء): ج١/ص١٣٣ (المقدمة العاشرة) وج٣/ص١٦٥ (كتاب الأدلة الشرعية) | الكلمات المفتاحية: القياس، أصول الفقه، أدلة التشريع',
  evidence = 'الموافقات ج١/ص١٣٣: «فَلَيْسَ الْقِيَاسُ مِنْ تَصَرُّفَاتِ الْعُقُولِ مَحْضًا، وَإِنَّمَا تَصَرَّفَتْ فِيهِ مِنْ تَحْتِ نَظَرِ الْأَدِلَّةِ، وَعَلَى حَسَبِ مَا أَعْطَتْهُ مِنْ إِطْلَاقٍ أَوْ تَقْيِيدٍ… فَإِنَّا إِذَا دَلَّنَا الشَّرْعُ عَلَى أَنَّ إِلْحَاقَ الْمَسْكُوتِ عَنْهُ بِالْمَنْصُوصِ عَلَيْهِ مُعْتَبَرٌ، وَأَنَّهُ مِنَ الْأُمُورِ الَّتِي قَصَدَهَا الشَّارِعُ، وَأَمَرَ بِهَا، وَنَبَّهَ النَّبِيُّ -صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- عَلَى الْعَمَلِ بِهَا؛ فَأَيْنَ اسْتِقْلَالُ الْعَقْلِ بِذَلِكَ؟ بَلْ هُوَ مهتدٍ فِيهِ بِالْأَدِلَّةِ الشَّرْعِيَّةِ، يَجْرِي بِمِقْدَارِ مَا أَجْرَتْهُ، وَيَقِفُ حَيْثُ وَقَفَتْهُ». وعدُّه رابعَ الأدلة ج٣/ص١٦٥: «وَهِيَ: الْكِتَابُ، وَالسُّنَّةُ، وَالْإِجْمَاعُ، وَالْقِيَاسُ».',
