-- 9f11edcb | ما هي الأحكام التكليفية الخمسة في الفقه الإسلامي؟
UPDATE qa_questions SET
  answer = 'خطابُ التكليف عند الشاطبي في الموافقات «ينحصر في الخمسة»: الواجب (يُثاب فاعله ويُعاقَب تاركه)، والمندوب أو المستحب (يُثاب فاعله ولا يُعاقَب تاركه)، والمباح، والمكروه (يُثاب تاركه ولا يُعاقَب فاعله)، والمحرَّم (يُعاقَب فاعله ويُثاب تاركه). والمباحُ عنده «هو المخيَّر فيه بين الفعل والترك، من غير مدح ولا ذم، لا على الفعل ولا على الترك»، فهو «من حيث هو مباح لا يكون مطلوب الفعل ولا مطلوب الاجتناب»، ولذلك لا يكون تاركه مطيعًا بتركه «لعدم تعلُّق الطلب بالترك». وهذا الحصرُ في خمسةٍ هو تقسيم الجمهور؛ وقد حكت الموافقات نفسُها أن الحنفية فرَّقوا بين الفرض والواجب، وردَّت تلك التفرقة إلى تقدُّم اعتبار الكتاب على اعتبار السنة — فالعدّ والتسمية ليسا محلّ اتفاق.',
  reference = 'الموافقات للشاطبي، ت مشهور بن حسن آل سلمان (٧ أجزاء): ج١/ص١٦٩ (كتاب الأحكام) وج١/ص١٧١–١٧٢ (المسألة الأولى في المباح) وج٤/ص٣٠٨ | الكلمات المفتاحية: الأحكام التكليفية الخمسة',
  evidence = 'الموافقات ج١/ص١٦٩ في افتتاح كتاب الأحكام: «وَالْأَحْكَامُ الشَّرْعِيَّةُ قِسْمَانِ: أَحَدُهُمَا يَرْجِعُ إِلَى خِطَابِ التَّكْلِيفِ وَالْآخَرُ يَرْجِعُ إِلَى خِطَابِ الْوَضْعِ؛ فَالْأَوَّلُ يَنْحَصِرُ فِي الْخَمْسَةِ». وحدُّ المباح فيها ج١/ص١٧٢: «أَنَّ الْمُبَاحَ عِنْدَ الشَّارِعِ هُوَ الْمُخَيَّرُ فِيهِ بَيْنَ الْفِعْلِ وَالتَّرْكِ، مِنْ غَيْرِ مَدْحٍ وَلَا ذَمٍّ، لَا عَلَى الْفِعْلِ وَلَا عَلَى التَّرْكِ»، وقبله ج١/ص١٧١: «الْمُبَاحُ مِنْ حَيْثُ هُوَ مُبَاحٌ لَا يَكُونُ مَطْلُوبَ الْفِعْلِ، وَلَا مَطْلُوبَ الِاجْتِنَابِ»، ولذلك «لَمْ يُتَصَوَّرْ أَنْ يَكُونَ التَّارِكُ بِهِ مُطِيعًا لِعَدَمِ تَعَلُّقِ الطَّلَبِ بِالتَّرْكِ؛ فَإِنَّ الطَّاعَةَ لَا تَكُونُ إِلَّا مَعَ الطَّلَبِ». ⚠️ وليس الحصرُ في خمسةٍ محلَّ اتفاقٍ في العدّ والتسمية: الموافقات نفسُها ج٤/ص٣٠٨ تحكي «وَمَا فَرَّقَ بِهِ الْحَنَفِيَّةُ بَيْنَ الْفَرْضِ وَالْوَاجِبِ رَاجِعٌ إِلَى تَقَدُّمِ اعتبار الكتاب»، وتمامُه ج٤/ص٣٠٩: «عَلَى اعْتِبَارِ السُّنَّةِ، وَأَنَّ اعْتِبَارَ الْكِتَابِ أَقْوَى مِنِ اعْتِبَارِ السُّنَّةِ، وَقَدْ لَا يُخَالِفُ غَيْرُهُمْ فِي مَعْنَى تِلْكَ التَّفْرِقَةِ».',
  verification_status = 'verified'
WHERE id = '9f11edcb-3f01-412c-a664-1df785c2923f'
  AND reference = 'كتب أصول الفقه | الكلمات المفتاحية: الأحكام التكليفية الخمسة'
  AND evidence = 'تصنيف أصولي متفق عليه بين جمهور الفقهاء، مبسوط في كتب أصول الفقه.'
  AND answer = 'الواجب (يُثاب فاعله ويُعاقَب تاركه)، والمستحب (يُثاب فاعله ولا يُعاقَب تاركه)، والمباح (لا ثواب ولا عقاب)، والمكروه (يُثاب تاركه ولا يُعاقَب فاعله)، والمحرَّم (يُعاقَب فاعله ويُثاب تاركه).';

-- a0724439 | ما هي مصادر التشريع الإسلامي المتفق عليها؟
UPDATE qa_questions SET
  answer = 'الكتابُ، والسنةُ، والإجماعُ، والقياسُ — وهذا نصُّ الشاطبي في افتتاح كتاب الأدلة الشرعية من الموافقات: «وهي: الكتاب، والسنة، والإجماع، والقياس»؛ وهي الأدلة الأربعة المتفق على حجيتها عند جمهور الفقهاء، إضافةً لأدلةٍ مختلَفٍ فيها كالاستحسان والمصالح المرسلة. ورتبتُها ليست واحدة عنده: «رتبة السنة التأخُّر عن الكتاب في الاعتبار»، لأن «الكتاب مقطوع به، والسنة مظنونة… والمقطوع به مقدَّم على المظنون» — والمراد تأخُّرُها في رتبة الاعتبار لا اطِّراحُها.',
  reference = 'الموافقات للشاطبي، ت مشهور بن حسن آل سلمان (٧ أجزاء): ج٣/ص١٦٥ (كتاب الأدلة الشرعية) وج٤/ص٢٩٤ | الكلمات المفتاحية: مصادر التشريع، أدلة الفقه',
  evidence = 'الموافقات ج٣/ص١٦٥ في افتتاح كتاب الأدلة الشرعية: «يَتَعَلَّقُ بِهَا عَلَى الْجُمْلَةِ، وَفِيمَا يَتَعَلَّقُ بِكُلِّ وَاحِدٍ مِنْهَا عَلَى التَّفْصِيلِ وَهِيَ: الْكِتَابُ، وَالسُّنَّةُ، وَالْإِجْمَاعُ، وَالْقِيَاسُ». ورتبتُها ليست واحدة، ج٤/ص٢٩٤: «الْمَسْأَلَةُ الثَّانِيَةُ: رُتْبَةُ السُّنَّةِ التَّأَخُّرُ عَنِ الْكِتَابِ فِي الِاعْتِبَارِ، وَالدَّلِيلُ عَلَى ذَلِكَ أُمُورٌ: أَحَدُهَا: أَنَّ الْكِتَابَ مَقْطُوعٌ بِهِ، وَالسُّنَّةَ مَظْنُونَةٌ، وَالْقَطْعُ فِيهَا إِنَّمَا يَصِحُّ فِي الْجُمْلَةِ لَا فِي التَّفْصِيلِ، بِخِلَافِ الْكِتَابِ؛ فَإِنَّهُ مَقْطُوعٌ بِهِ فِي الْجُمْلَةِ وَالتَّفْصِيلِ، وَالْمَقْطُوعُ بِهِ مُقَدَّمٌ عَلَى الْمَظْنُونِ».',
