-- cccffc77 | ما هي القراءات القرآنية المتواترة؟
UPDATE qa_questions SET
  answer = 'أوجهٌ متعددة في نطق ألفاظ القرآن، ثبتت بالرواية عن النبي ﷺ، وأشهرُها قراءاتُ الأئمة السبعة ثم العشرة. لكنّ التصحيحَ عند السيوطي في الإتقان ليس بنسبة القراءة إلى قارئٍ بعينه، بل بضابط ابن الجزري في «النشر» الذي ارتضاه ونقله وسمَّى قائله أحسنَ من تكلم في الباب — وهو ثلاثة أركان: أن توافق القراءةُ العربيةَ ولو بوجه، وأن توافق أحدَ المصاحف العثمانية ولو احتمالًا، وأن يصحّ سندُها؛ فمتى اجتمعت فهي «القراءة الصحيحة التي لا يجوز ردها ولا يحل إنكارها»، سواء كانت عن السبعة أم العشرة أم عن غيرهم من الأئمة المقبولين، «ومتى اختلّ ركن من هذه الأركان الثلاثة أُطلق عليها ضعيفة أو شاذة أو باطلة سواء كانت عن السبعة أو عمَّن هو أكبر منهم». ولذلك نبَّه السيوطي على أن قصرَ المتواتر على السبع — وهو قول البلقيني — «فيه نظر»، ونقل عن أبي شامة أن «القراءة المنسوبة إلى كل قارئ من السبعة وغيرهم منقسمة إلى المجمع عليه والشاذ». والاختلافُ بين القراءات الصحيحة اختلافُ تنوُّعٍ لا تضادّ.',
  reference = 'الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (٤ أجزاء): ج١/ص٢٥٨–٢٥٩ (النوع الثاني والثالث والرابع والخامس والسادس والسابع والعشرون: معرفة المتواتر والمشهور والآحاد والشاذ والموضوع والمدرج) | الكلمات المفتاحية: القراءات السبع',
  evidence = 'الإتقان ج١/ص٢٥٨: «اعْلَمْ أَنَّ الْقَاضِيَ جَلَالَ الدِّينِ الْبَلْقِينِيَّ قَالَ: الْقِرَاءَةُ تَنْقَسِمُ إِلَى مُتَوَاتِرٍ وَآحَادٍ وَشَاذٍّ فَالْمُتَوَاتِرُ الْقِرَاءَاتُ السَّبْعَةُ الْمَشْهُورَةُ وَالْآحَادُ قِرَاءَاتُ الثَّلَاثَةِ الَّتِي هِيَ تَمَامُ الْعَشْرِ… وَهَذَا الْكَلَامُ فِيهِ نَظَرٌ يُعْرَفُ مِمَّا سَنَذْكُرُهُ وَأَحْسَنُ مَنْ تَكَلَّمَ فِي هَذَا النَّوْعِ إِمَامُ الْقُرَّاءِ فِي زَمَانِهِ… أَبُو الْخَيْرِ بْنُ الْجَزَرِيِّ قَالَ فِي أَوَّلِ كِتَابِهِ النَّشْرِ: كُلُّ قِرَاءَةٍ وَافَقَتِ الْعَرَبِيَّةَ وَلَوْ بِوَجْهٍ وَوَافَقَتْ أَحَدَ الْمَصَاحِفِ الْعُثْمَانِيَّةِ وَلَوِ احْتِمَالًا وَصَحَّ سَنَدُهَا فَهِيَ الْقِرَاءَةُ الصَّحِيحَةُ الَّتِي لَا يَجُوزُ رَدُّهَا وَلَا يَحِلُّ إِنْكَارُهَا بَلْ هِيَ مِنَ الْأَحْرُفِ السَّبْعَةِ الَّتِي نَزَلَ بِهَا الْقُرْآنُ وَوَجَبَ عَلَى النَّاسِ قَبُولُهَا سَوَاءً كَانَتْ عَنِ الْأَئِمَّةِ السَّبْعَةِ أَمْ عَنِ الْعَشْرَةِ أَمْ عَنْ غَيْرِهِمْ مِنَ الْأَئِمَّةِ الْمَقْبُولِينَ وَمَتَى اخْتَلَّ رُكْنٌ مِنْ هَذِهِ الْأَرْكَانِ الثَّلَاثَةِ أُطْلِقَ عَلَيْهَا ضَعِيفَةٌ أَوْ شَاذَّةٌ أَوْ بَاطِلَةٌ سَوَاءٌ كَانَتْ عَنِ السَّبْعَةِ أو عَمَّنْ هُوَ أَكْبَرُ مِنْهُمْ. هَذَا هُوَ الصَّحِيحُ عِنْدَ أَئِمَّةِ التَّحْقِيقِ مِنَ السَّلَفِ وَالْخَلَفِ». وفي آخر ج١/ص٢٥٨ عن أبي شامة في المرشد الوجيز: «لَا يَنْبَغِي أَنْ يُغْتَرَّ بِكُلِّ قِرَاءَةٍ تُعْزَى»، وتمامُه ج١/ص٢٥٩: «إِلَى أَحَدِ السَّبْعَةِ وَيُطْلَقَ عَلَيْهَا لَفْظُ الصِّحَّةِ وَأَنَّهَا أُنْزِلَتْ هَكَذَا إِلَّا إِذَا دَخَلَتْ فِي ذَلِكَ الضَّابِطِ»، وأن «الْقِرَاءَةَ الْمَنْسُوبَةَ إِلَى كُلِّ قَارِئٍ مِنَ السَّبْعَةِ وَغَيْرِهِمْ مُنْقَسِمَةٌ إِلَى الْمُجْمَعِ عَلَيْهِ وَالشَّاذِّ»، وعن الداني: «إِذَا ثَبَتَتِ الرِّوَايَةُ لَمْ يَرُدَّهَا قِيَاسُ عَرَبِيَّةٍ وَلَا فُشُوُّ لُغَةٍ لِأَنَّ الْقِرَاءَةَ سُنَّةٌ مُتَّبَعَةٌ يَلْزَمُ قَبُولُهَا وَالْمَصِيرُ إِلَيْهَا».',
  verification_status = 'verified'
WHERE id = 'cccffc77-1324-44ea-87e5-82605f72bba7'
  AND reference = 'كتب علوم القرآن | الكلمات المفتاحية: القراءات السبع'
  AND evidence = 'مبحث مستقل في علوم القرآن، مبسوط في كتب القراءات.'
  AND answer = 'أوجه متعددة صحيحة الإسناد متواترة عن النبي ﷺ في نطق بعض ألفاظ القرآن، أشهرها القراءات السبع (ثم العشر)، وكلها كلام الله نزل به الوحي، لا اختلاف يمس أصل المعنى.';

-- d09d91d4 | ما معنى "الوجوه والنظائر" في علوم القرآن؟
UPDATE qa_questions SET
  answer = 'هما مصطلحان متمايزان لا مصطلح واحد، ونصُّ السيوطي في الإتقان يفصل بينهما: «فالوجوه للفظ المشترك الذي يُستعمل في عدة معانٍ كلفظ الأمة… والنظائر كالألفاظ المتواطئة»؛ فالوجوهُ تعدُّدُ معاني اللفظ الواحد بحسب سياقاته، والنظائرُ الألفاظُ المتواطئةُ التي يجمعها معنًى واحد في مواضع كثيرة. ومثالُ الوجوه لفظُ «الهدى» — قال السيوطي: «يأتي على تسعة عشر وجهًا»، منها الثبات في ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾، والبيان في ﴿أُولَئِكَ عَلَى هُدًى مِنْ رَبِّهِمْ﴾، والدين في ﴿إِنَّ الْهُدَى هُدَى اللَّهِ﴾، والإيمان في ﴿وَيَزِيدُ اللَّهُ الَّذِينَ اهْتَدَوْا هُدًى﴾. وأولُ من صنَّف فيه مقاتل بن سليمان، ثم ابن الجوزي وابن الدامغاني وابن فارس وغيرهم، وقد عدَّه بعضهم من أنواع إعجاز القرآن «حيث كانت الكلمة الواحدة تنصرف إلى عشرين وجهًا وأكثر وأقلّ ولا يوجد ذلك في كلام البشر».',
  reference = 'الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (٤ أجزاء): ج٢/ص١٤٤–١٤٦ (النوع التاسع والثلاثون: في معرفة الوجوه والنظائر) | الكلمات المفتاحية: الوجوه والنظائر',
  evidence = 'الإتقان ج٢/ص١٤٤: «النَّوْعُ التَّاسِعُ وَالثَّلَاثُونَ: فِي مَعْرِفَةِ الْوُجُوهِ وَالنَّظَائِرِ صَنَّفَ فِيهَا قَدِيمًا مُقَاتِلُ بْنُ سُلَيْمَانَ وَمِنَ الْمُتَأَخِّرِينَ ابْنُ الْجَوْزِيِّ وَابْنُ الدَّامِغَانِيِّ وَأَبُو الْحُسَيْنِ مُحَمَّدُ بْنُ عَبْدِ الصَّمَدِ الْمِصْرِيُّ وَابْنُ فَارِسٍ وَآخَرُونَ. فَالْوُجُوهُ لِلَّفْظِ الْمُشْتَرَكِ الَّذِي يُسْتَعْمَلُ فِي عِدَّةِ مَعَانٍ كَلَفْظِ الْأُمَّةِ وَقَدْ أَفْرَدْتُ فِي هَذَا الْفَنِّ كِتَابًا سَمَّيْتُهُ ” مُعْتَرَكُ الْأَقْرَانِ فِي مُشْتَرَكِ الْقُرْآنِ ” . وَالنَّظَائِرُ كَالْأَلْفَاظِ الْمُتَوَاطِئَةِ. وَقِيلَ: النَّظَائِرُ فِي اللَّفْظِ وَالْوُجُوهُ فِي الْمَعَانِي وَضُعِّفَ… وَقَدْ جَعَلَ بَعْضُهُمْ ذَلِكَ مِنْ أَنْوَاعِ مُعْجِزَاتِ الْقُرْآنِ حَيْثُ كَانَتِ الْكَلِمَةُ الْوَاحِدَةُ تَنْصَرِفُ إِلَى عِشْرِينَ وَجْهًا وَأَكْثَرَ وَأَقَلَّ وَلَا يُوجَدُ ذَلِكَ فِي كَلَامِ الْبَشَرِ». وج٢/ص١٤٥ في المثال: «{الْهُدَى} : يَأْتِي على تسعة عَشَرَ وَجْهًا: بِمَعْنَى الثَّبَاتِ: {اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ}»، وتمامُه ج٢/ص١٤٦: «وَالْبَيَانِ: {أُولَئِكَ عَلَى هُدىً مِنْ رَبِّهِمْ} . وَالدِّينِ: {إِنَّ الْهُدَى هُدَى اللَّهِ} . وَالْإِيمَانِ: {وَيَزِيدُ اللَّهُ الَّذِينَ اهْتَدَوْا هُدىً}».',
  verification_status = 'verified'
WHERE id = 'd09d91d4-66b1-4c5c-8cee-819156b8607a'
  AND reference = 'كتب علوم القرآن | الكلمات المفتاحية: الوجوه والنظائر'
  AND evidence = 'مبحث مستقل في علوم القرآن، له كتب مصنَّفة كالوجوه والنظائر لمقاتل بن سليمان.'
  AND answer = 'اللفظ الواحد الذي يرد في القرآن بمعانٍ مختلفة بحسب سياقاته المتعددة (كلفظ "الهدى" الذي يرد بمعنى البيان تارة والإيمان تارة أخرى)، وهو باب دقيق يحتاج تأمل السياق لكل موضع.';

-- f8c435b0 | ما معنى قاعدة "سد الذرائع" في الفقه الإسلامي؟
UPDATE qa_questions SET
  answer = 'منعُ فعلٍ مباحٍ في أصله لأنه وسيلةٌ تُفضي إلى مفسدةٍ أو محرَّم — وهو عند الشاطبي في الموافقات «راجعٌ إلى طلب ترك ما ثبت طلبُ فعله لعارضٍ يعرض»، و«أصلٌ متفق عليه في الجملة، وإن اختلف العلماء في تفاصيله»؛ فليس مذهبًا خاصًّا بالمالكية والحنابلة، وإنما محلُّ الخلاف تفاصيلُه لا أصلُه. ومن أمثلته المنصوصة قوله تعالى ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقُولُوا رَاعِنَا﴾ وقوله ﴿وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ﴾، وكفُّه ﷺ عن قتل المنافقين «لأنه ذريعة إلى قول الكفار: إن محمدًا يقتل أصحابه». والتفصيلُ عند الشاطبي بحسب درجة الإفضاء: فما أداؤه إلى المفسدة نادرٌ «فهو على أصله من الإذن»، وما أداؤه إليها ظنيٌّ فـ«اعتبار الظن هو الأرجح» فيُمنع، وما أداؤه إليها كثيرٌ لا غالبٌ ولا نادرٌ فـ«موضع نظرٍ والتباس»، الأصلُ فيه الإذن «كمذهب الشافعي وغيره»، «إلا أن مالكًا اعتبره في سد الذرائع بناءً على كثرة القصد وقوعًا».',
  reference = 'الموافقات للشاطبي، ت مشهور بن حسن آل سلمان (٧ أجزاء): ج٣/ص٧٤ و٧٥ و٧٧ (القسم الثاني: مقاصد المكلف) وج٣/ص٥٠٩ | الكلمات المفتاحية: سد الذرائع',
  evidence = 'الموافقات ج٣/ص٥٠٩: «فباب سد الذرائع… رَاجِعٌ إِلَى طَلَبِ تَرْكِ مَا ثَبَتَ طَلَبُ فِعْلِهِ لِعَارِضٍ يَعْرِضُ، وَهُوَ أَصْلٌ مُتَّفَقٌ عَلَيْهِ فِي الْجُمْلَةِ، وَإِنِ اخْتَلَفَ الْعُلَمَاءُ فِي تَفَاصِيلِهِ؛ فَلَيْسَ الْخِلَافُ فِي بَعْضِ الْفُرُوعِ مِمَّا يُبْطِلُ دَعْوَى الْإِجْمَاعِ فِي الْجُمْلَةِ؛ لِأَنَّهُمُ اتَّفَقُوا عَلَى مِثْلِ قَوْلِ اللَّهِ تَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقُولُوا رَاعِنَا} … وَقَوْلِهِ: {وَلا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ}». وتفصيلُ أقسامه ج٣/ص٧٤: «وَأَمَّا السَّادِسُ: وَهُوَ مَا يَكُونُ أَدَاؤُهُ إِلَى الْمَفْسَدَةِ نَادِرًا؛ فَهُوَ عَلَى أَصْلِهِ مِنَ الْإِذْنِ، لِأَنَّ الْمَصْلَحَةَ إِذَا كَانَتْ غَالِبَةً؛ فَلَا اعْتِبَارَ بِالنُّدُورِ فِي انْخِرَامِهَا»؛ وج٣/ص٧٥: «وَأَمَّا السَّابِعُ: وَهُوَ مَا يَكُونُ أَدَاؤُهُ إِلَى الْمَفْسَدَةِ ظَنِّيًّا؛ فَيَحْتَمِلُ الْخِلَافَ… وَلَكِنَّ اعْتِبَارَ الظَّنِّ هُوَ الْأَرْجَحُ»، ومنه «أَنَّ الْمَنْصُوصَ عَلَيْهِ مِنْ سَدِّ الذَّرَائِعِ دَاخِلٌ فِي هَذَا الْقِسْمِ»؛ وج٣/ص٧٧: «وَأَمَّا الثَّامِنُ: وَهُوَ مَا يَكُونُ أَدَاؤُهُ إِلَى الْمَفْسَدَةِ كَثِيرًا لَا غَالِبًا وَلَا نَادِرًا؛ فَهُوَ مَوْضِعُ نَظَرٍ وَالْتِبَاسٍ، وَالْأَصْلُ فِيهِ الْحَمْلُ عَلَى الْأَصْلِ مِنْ صِحَّةِ الْإِذْنِ كَمَذْهَبِ الشَّافِعِيِّ وَغَيْرِهِ… إِلَّا أَنَّ مَالِكًا اعْتَبَرَهُ فِي سَدِّ الذَّرَائِعِ بِنَاءً عَلَى كَثْرَةِ الْقَصْدِ وُقُوعًا». ومن أمثلته المنصوصة ج٣/ص٧٦: «وَكَانَ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ يَكُفُّ عَنْ قَتْلِ الْمُنَافِقِينَ؛ لِأَنَّهُ ذَرِيعَةٌ إِلَى قَوْلِ الْكُفَّارِ: إِنَّ مُحَمَّدًا يَقْتُلُ أَصْحَابَهُ».',
